result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/modal/src/Modal.tsx", "content": "import * as React from "react";
import { createPortal } from "react-dom";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(", ");

export interface ModalProps {
  /** Whether the modal is rendered. */
  open: boolean;
  /** Called when the modal requests to close (Escape, backdrop click). */
  onClose: () => void;
  /** id of the element that titles this dialog (for aria-labelledby). */
  labelledBy: string;
  children: React.ReactNode;
}

/**
 * Accessible modal dialog.
 *
 * - Rendered into a portal attached to document.body.
 * - Traps Tab / Shift+Tab within its focusable descendants.
 * - Focuses the first focusable element on open.
 * - Restores focus to the previously focused element on close.
 * - Closes on Escape and on backdrop clicks; clicks inside the panel do not close it.
 */
export function Modal({ open, onClose, labelledBy, children }: ModalProps) {
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const previouslyFocused = React.useRef<HTMLElement | null>(null);

  // Remember the trigger, focus the first focusable inside the panel.
  React.useEffect(() => {
    if (!open) return;
    previouslyFocused.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;

    const panel = panelRef.current;
    if (panel) {
      const first = panel.querySelector<HTMLElement>(FOCUSABLE_SELECTOR);
      if (first) first.focus();
    }

    const previouslyFocusedEl = previouslyFocused.current;
    return () => {
      // Restore focus to the trigger (or whatever was focused before opening).
      previouslyFocusedEl?.focus();
    };
  }, [open]);

  // Escape closes; Tab wraps within the panel.
  React.useEffect(() => {
    if (!open) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose();
        return;
      }

      if (event.key !== "Tab") return;

      const panel = panelRef.current;
      if (!panel) return;

      const focusables = Array.from(
        panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)
      ).filter((el) => el.offsetParent !== null || el === document.activeElement);

      if (focusables.length === 0) return;

      const currentIndex = focusables.indexOf(
        document.activeElement as HTMLElement
      );

      let nextIndex: number;
      if (event.shiftKey) {
        nextIndex =
          currentIndex <= 0 ? focusables.length - 1 : currentIndex - 1;
      } else {
        nextIndex =
          currentIndex === focusables.length - 1 || currentIndex === -1
            ? 0
            : currentIndex + 1;
      }

      event.preventDefault();
      focusables[nextIndex].focus();
    };

    document.addEventListener("keydown", handleKeyDown, true);
    return () => document.removeEventListener("keydown", handleKeyDown, true);
  }, [open, onClose]);

  if (!open) return null;

  const handleBackdropMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
    // Only react to presses on the backdrop itself, never inside the panel.
    if (event.target === event.currentTarget) {
      onClose();
    }
  };

  return createPortal(
    <div
      data-testid="modal-backdrop"
      onMouseDown={handleBackdropMouseDown}
      style={{
        position: "fixed",
        inset: 0,
        display: "grid",
        placeItems: "center",
      }}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelledBy}
        data-testid="modal-panel"
        onMouseDown={(event) => event.stopPropagation()}
        onKeyDown={(event) => event.stopPropagation()}
      >
        {children}
      </div>
    </div>,
    document.body
  );
}

export default Modal;
"})
