function Harness({
  onClose,
  open: openProp,
}: {
  onClose?: () => void;
  open?: boolean;
}) {
  const [open, setOpen] = React.useState(openProp ?? false);
  const close = onClose ?? (() => setOpen(false));
  return (
    <div>
      <button type="button" onClick={() => setOpen(true)}>
        Open
      </button>
      <Modal open={open} onClose={close} labelledBy="modal-title">
        <h2 id="modal-title">My Title</h2>
        <input type="text" aria-label="Field one" />
        <button type="button">First</button>
        <button type="button">Second</button>
      </Modal>
    </div>
  );
}

describe("Modal", () => {
  function openModal() {
    const user = userEvent.setup();
    render(<Harness />);
    const trigger = screen.getByRole("button", { name: "Open" });
    trigger.focus();
    user.click(trigger);
    return { user, trigger };
  }

  it("renders into a portal with role=dialog, aria-modal and aria-labelledby", () => {
    render(<Harness open />);

    const dialog = screen.getByRole("dialog");
    expect(dialog).not.toBeNull();
    // Portal: rendered outside the React root container.
    const root = screen.getByRole("button", { name: "Open" }).parentElement!;
    expect(root.contains(dialog)).toBe(false);
    expect(document.body.contains(dialog)).toBe(true);

    expect(dialog).toHaveAttribute("aria-modal", "true");
    expect(dialog).toHaveAttribute("aria-labelledby", "modal-title");
    expect(screen.getByText("My Title")).toHaveAttribute("id", "modal-title");
  });

  it("focuses the first focusable element on open", async () => {
    openModal();
    await waitForTick();

    expect(screen.getByLabelText("Field one")).toHaveFocus();
  });

  it("restores focus to the previously focused trigger on close (Escape)", async () => {
    const { user, trigger } = openModal();
    await waitForTick();
    expect(screen.getByRole("dialog")).toBeInTheDocument();

    await user.keyboard("{Escape}");

    expect(screen.queryByRole("dialog")).not.toBeInTheDocument();
    expect(trigger).toHaveFocus();
  });

  it("traps Tab: wraps from last focusable to first", async () => {
    const { user } = openModal();
    await waitForTick();

    const input = screen.getByLabelText("Field one");
    const first = screen.getByRole("button", { name: "First" });
    const second = screen.getByRole("button", { name: "Second" });

    expect(input).toHaveFocus();
    await user.tab();
    expect(first).toHaveFocus();
    await user.tab();
    expect(second).toHaveFocus();

    // Tab from the last focusable wraps to the first.
    await user.tab();
    expect(input).toHaveFocus();

    // ...and keeps cycling inside the dialog.
    await user.tab();
    expect(first).toHaveFocus();
  });

  it("traps Shift+Tab: wraps from first focusable to last", async () => {
    const { user } = openModal();
    await waitForTick();

    const input = screen.getByLabelText("Field one");
    const second = screen.getByRole("button", { name: "Second" });

    expect(input).toHaveFocus();
    await user.tab({ shift: true });
    expect(second).toHaveFocus();
  });

  it("closes on Escape but not on clicks inside the panel", async () => {
    const onClose = vi.fn();
    const user = userEvent.setup();
    render(<Harness open onClose={onClose} />);
    await waitForTick();

    // Clicking a button inside the panel does not close...
    await user.click(screen.getByRole("button", { name: "Second" }));
    expect(onClose).not.toHaveBeenCalled();
    expect(screen.getByRole("dialog")).toBeInTheDocument();

    // ...nor does clicking inert parts of the panel itself.
    await user.click(screen.getByTestId("modal-panel"));
    expect(onClose).not.toHaveBeenCalled();

    // Escape closes.
    await user.keyboard("{Escape}");
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("closes on backdrop click", async () => {
    const onClose = vi.fn();
    const user = userEvent.setup();
    render(<Harness open onClose={onClose} />);
    await waitForTick();

    await user.click(screen.getByTestId("modal-backdrop"));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("renders nothing when closed", () => {
    render(<Harness open={false} />);
    expect(screen.queryByRole("dialog")).not.toBeInTheDocument();
  });
});

describe("Demo", () => {
  it("opens via trigger, traps focus, closes via backdrop and restores focus", async () => {
    const user = userEvent.setup();
    render(<Demo />);

    const trigger = screen.getByRole("button", { name: "Open modal" });
    await user.click(trigger);

    const dialog = screen.getByRole("dialog");
    expect(dialog).toHaveAttribute("aria-labelledby", "modal-title");
    expect(
      screen.getByText("Confirm your choice")
    ).toHaveAttribute("id", "modal-title");

    // First focusable is the input; cycle through both buttons.
    await waitForTick();
    expect(screen.getByPlaceholderText("Your name")).toHaveFocus();
    await user.tab();
    expect(screen.getByRole("button", { name: "Cancel" })).toHaveFocus();
    await user.tab();
    expect(screen.getByRole("button", { name: "Confirm" })).toHaveFocus();
    await user.tab(); // wrap
    expect(screen.getByPlaceholderText("Your name")).toHaveFocus();

    // Backdrop click closes and focus returns to the trigger.
    await user.click(screen.getByTestId("modal-backdrop"));
    expect(screen.queryByRole("dialog")).not.toBeInTheDocument();
    expect(trigger).toHaveFocus();
  });
});

async function waitForTick() {
  await actAndWait();
